#ifndef CONFIG_H
#define CONFIG_H

#include <fmt/format.h>
#include <yaml-cpp/yaml.h>
#include <sys/stat.h>
#include <concepts>
#include <functional>
#include <initializer_list>
#include <memory>
#include <regex>
#include <string>
#include <string_view>
#include <utility>
#include <unordered_map>

namespace ws {
namespace cfg {

class VarBase {
public:
    VarBase(std::string name, std::string description) : name_(std::move(name)), description_(std::move(description)) {}
    virtual ~VarBase() = default;

    std::string_view Name() const { return name_; }
    std::string_view Description() const { return description_; }
    virtual std::string ToString() = 0;
    virtual void FromString(std::string_view str) = 0;

protected:
    std::string name_;
    std::string description_;
};

template <typename T, typename FromStr, typename ToStr>
class Var : public VarBase {
public:
    using Ptr = std::shared_ptr<Var>;

    Var(std::string name, std::string description, const T& val) :
        VarBase(std::move(name), std::move(description)), val_(val) {}

    std::string ToString() override {
        return fmt::format("{}", val_);
    }

    void FromString(std::string_view str) override {
        // Implement conversion logic here if needed.
        // For simplicity, we assume the string can be directly converted to T.
        val_ = static_cast<T>(std::stoul(str.data()));
    }

    T GetValue() const { return val_; }
    void SetValue(const T& val) { val_ = val; }

private:
    T val_;
};

class Config {
public:
    using VarPtr = std::shared_ptr<VarBase>;

    Config(std::string name) : name_(std::move(name)) {}

    std::string_view Name() const { return name_; }

    template <typename T>
    typename Var<T>::Ptr Lookup(const std::string_view name, const T& default_val) {
        auto it = vars_.find(name.data());
        if (it != vars_.end()) {
            return std::dynamic_pointer_cast<Var<T>>(it->second);
        } else {
            auto var = std::make_shared<Var<T>>(std::string(name), "", default_val);
            vars_[name.data()] = var;
            return var;
        }
    }

    void LoadYaml(const YAML::Node& root) {
        for (auto& node : root) {
            std::string name = node.first().as<std::string>();
            YAML::Node value_node = node.second();

            if (!value_node.IsDefined()) continue;

            // Attempt to convert the YAML node to a string.
            std::string value_str = value_node.as<std::string>();

            auto var = Lookup<int>(name, 0); // Assuming int for now.
            var->FromString(value_str);
        }
    }

private:
    std::string name_;
    std::unordered_map<std::string, VarBase::Ptr> vars_;
};

constexpr int invalid_file_descriptor = -1;

bool IsValidFileDescriptor(int fd) {
    return fd >= 0;
}

} // namespace cfg
} // namespace ws

#endif // CONFIG_H
